import { readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
const catalog = JSON.parse(await readFile('hidden/cases.json','utf8'));
const variants = JSON.parse(await readFile('scratch/validation/variants-summary.json','utf8'));
const killed = new Set(variants.flatMap(v => v.name === 'broken-import' ? [] : v.failures));
const uncovered = catalog.filter(t => t.counts && !killed.has(t.name));
if (uncovered.length) throw new Error(JSON.stringify(uncovered));
console.log('All 16 counted cases fail under at least one behavioral mutation (excluding broken import).');
const paths = ['hidden/acceptance.test.ts', 'hidden/cases.json', 'hidden/store-counter.ts', 'rubric.md', 'run-hidden.mjs', 'VALIDATION.md'].sort();
const files = {};
for (const path of paths) files[path] = createHash('sha256').update(await readFile(path)).digest('hex');
console.log(JSON.stringify({files},null,2));
NODE
